import React from "react";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  let radius = 150;

  let width = 30;
  let height = 30;

  let numPoints = 10;

  let x = window.outerWidth / 2 - radius - width / 2;
  let y = window.outerHeight / 2 - height / 2;

  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${x}, ${
            y - height / 2
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>

      <div
        className="circle"
        style={{
          offsetPath: `path("M ${x + radius * 2}, ${
            y - height / 2
          } a ${radius},${radius} 0 1,0 -${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 ${radius * 2},0")`
        }}
      ></div>

      <div
        className="circle"
        style={{
          offsetPath: `path("M ${x + radius}, ${
            y - height / 2 + radius
          } a ${radius},${radius} 0 1,0 0,-${
            radius * 2
          } a ${radius},${radius} 0 1,0 0,${radius * 2}")`
        }}
      ></div>

      <div
        className="circle"
        style={{
          offsetPath: `path("M ${x + radius}, ${
            y - height / 2 - radius
          } a ${radius},${radius} 0 1,0 0,${
            radius * 2
          } a ${radius},${radius} 0 1,0 0,-${radius * 2}")`
        }}
      ></div>
    </div>
  );
}

export default LoadingPage;
